async function chargeWithRetry(payment) {
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const key = newIdempotencyKey();          // dedup key
      const res = await psp.charge({ amount: payment.amount, key });
      return { status: 'succeeded', ref: res.ref };
    } catch (err) {
      // network error or timeout — try again
      continue;
    }
  }
  return { status: 'failed' };
}
